import RPi.GPIO as GPIO
import time

CLK = {{clk_pin}}
DT = {{dt_pin}}
SW = {{sw_pin}}

GPIO.setmode(GPIO.BCM)
GPIO.setup(CLK, GPIO.IN, pull_up_down=GPIO.PUD_UP)
GPIO.setup(DT, GPIO.IN, pull_up_down=GPIO.PUD_UP)
GPIO.setup(SW, GPIO.IN, pull_up_down=GPIO.PUD_UP)

counter = 0
last_clk = GPIO.input(CLK)
try:
    while True:
        clk = GPIO.input(CLK)
        if clk != last_clk:
            if GPIO.input(DT) != clk:
                counter += 1
            else:
                counter -= 1
            print(f"pos={counter}")
        last_clk = clk
        if GPIO.input(SW) == 0:
            print("sw pressed")
            time.sleep(0.2)
        time.sleep(0.001)
finally:
    GPIO.cleanup()
